@prefix iana: <http://www.iana.org/assignments/> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <file:///github/workspace/examples> ;
            sh:resultMessage "A STAC Catalog must not have more than one root link." ;
            sh:resultPath rdfs:seeAlso ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:QualifiedMaxCountConstraintComponent ;
            sh:sourceShape [ sh:message "A STAC Catalog must not have more than one root link." ;
                    sh:path rdfs:seeAlso ;
                    sh:qualifiedMaxCount 1 ;
                    sh:qualifiedValueShape [ sh:hasValue <http://www.iana.org/assignments/relation/root> ;
                            sh:path iana:relation ] ] ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
