[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <file:///github/workspace/examples> ;
            sh:resultMessage "A self link is STRONGLY RECOMMENDED for a STAC Catalog." ;
            sh:resultPath rdfs:seeAlso ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:QualifiedMinCountConstraintComponent ;
            sh:sourceShape [ sh:message "A self link is STRONGLY RECOMMENDED for a STAC Catalog." ;
                    sh:path rdfs:seeAlso ;
                    sh:qualifiedMinCount 1 ;
                    sh:qualifiedValueShape [ sh:hasValue <http://www.iana.org/assignments/relation/self> ;
                            sh:path iana:relation ] ;
                    sh:severity sh:Warning ] ],
        [ a sh:ValidationResult ;
            sh:focusNode <file:///github/workspace/examples> ;
            sh:resultMessage "A root link is STRONGLY RECOMMENDED for a STAC Catalog." ;
            sh:resultPath rdfs:seeAlso ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:QualifiedMinCountConstraintComponent ;
            sh:sourceShape [ sh:message "A root link is STRONGLY RECOMMENDED for a STAC Catalog." ;
                    sh:path rdfs:seeAlso ;
                    sh:qualifiedMinCount 1 ;
                    sh:qualifiedValueShape [ sh:hasValue <http://www.iana.org/assignments/relation/root> ;
                            sh:path iana:relation ] ;
                    sh:severity sh:Warning ] ] .

